import { createAdminClient } from '@/lib/supabase/server';
import { MemberManagementClient } from '@/components/dashboard/admin/MemberManagementClient';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import type { Member, Team, MemberWithTeamsAndRelations, MemberTeamRelation, EnrichedMember } from '@/lib/types';
import { createClient } from '@/lib/supabase/server';
import React, { Suspense } from 'react';
import Loading from './loading';

async function getMembersData() {
    const supabase = await createClient();
    const supabaseAdmin = await createAdminClient();

    // Run all independent queries in parallel
    const [membersResult, teamsResult, relationsResult, usersResult] = await Promise.all([
        supabase
            .from('members')
            .select('*')
            .is('deleted_at', null)
            .order('generation', { ascending: false })
            .order('student_number', { ascending: true }),
        supabase.from('teams').select('*'),
        supabase.from('member_team_relations').select('*'),
        supabaseAdmin.auth.admin.listUsers({ page: 1, perPage: 1000 }),
    ]);

    const { data: members, error: membersError } = membersResult;
    if (membersError) {
        console.error('Error fetching members:', membersError);
        throw membersError;
    }

